-- Pint's Tips: what items are used for on WoW Forever. Crafting reagents and recipe items come from Wowhead's WoW Forever
-- database (November 2026) - every recipe Forever has, for Alchemy, Blacksmithing, Cooking, Enchanting, Engineering, First Aid, Leatherworking, Mining and Tailoring - in place of the Classic ones;
-- quests keep the Classic list, with Forever's quest levels, less the quests Forever removed.
if type(issecretvalue) ~= "function" then return end   -- (WoW Forever only)
local U = PintsTipsUse
if not (U and U.prof and U.quest and U.qinfo and U.recipe) then return end
local SKILLS = { [129] = true, [164] = true, [165] = true, [171] = true, [185] = true, [186] = true, [197] = true, [202] = true, [333] = true }
-- drop the Classic entries for these professions, then add Forever's
for item, s in pairs(U.prof) do
	local keep = {}
	for part in s:gmatch("[^;]+") do local sk = tonumber(part:match("^(%d+)")); if not SKILLS[sk] then keep[#keep + 1] = part end end
	U.prof[item] = #keep > 0 and table.concat(keep, ";") or nil
end
for item, r in pairs(U.recipe) do if SKILLS[r[2]] then U.recipe[item] = nil end end
